import{_ as s,l as i,o as e,c as l,v as t,p as n,x as o,d as c,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"作用域与符号表","description":"","frontmatter":{"title":"作用域与符号表","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/scope-symtab.md","filePath":"cs/scope-symtab.md","lastUpdated":1789023840000}'),h={name:"cs/scope-symtab.md"};function _(m,a,E,f,u,A){const r=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="作用域与符号表" tabindex="-1">作用域与符号表 <a class="header-anchor" href="#作用域与符号表" aria-label="Permalink to &quot;作用域与符号表&quot;">​</a></h1><div class="epigraph"><p>同一拼写在不同括号结构里可以指不同的绑定；符号表按作用域层叠，查找从内向外。</p><footer>—— 据龙书第 2、6 章整理</footer></div><p>上一课<a href="/cs/ast-visitor">访问者与遍</a>给出了声明与使用的节点，但标识符仍是字符串。本课不重画 AST。缺口是：<strong>绑定</strong>——这个 <code>x</code> 指哪一次声明。词法作用域用块、过程、模块的嵌套；符号表是实现。类型是否匹配下一课才查。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>词法器已把标识符切出，CFG 不区分两个 <code>id</code>。若全局一张平表，内层声明无法遮蔽，块结束无法弹出。缺口是作用域栈：进入块 new 一层，声明插入当前层，查找从顶向下，离开块弹出。函数参数是一层，函数体是另一层或同一层带参数，按语言定。</p><p>动态作用域（按调用链查）不是本课主干；本栏默认词法作用域，与<a href="/cs/calling-convention-stack">调用约定</a>的栈帧对应：编译期绑定，运行时只是访问链或静态链。</p><h3 id="符号表不是散列课的复习" tabindex="-1">符号表不是散列课的复习 <a class="header-anchor" href="#符号表不是散列课的复习" aria-label="Permalink to &quot;符号表不是散列课的复习&quot;">​</a></h3><p><a href="/cs/hash-function">散列</a>是当前层的实现可选。结构是层叠映射：名字 \\(\\to\\) 声明记录（种类、类型占位、偏移稍后填）。本课要层叠与遮蔽，不重写链地址。</p><p><span class="marginnote">龙书用块结构语言当例子。C 的文件作用域与块作用域、函数原型的另层，细节不写完。后课类型检查假定每个使用已解析到唯一定义（或已报未声明）。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>遍历 AST。遇块：push。遇声明：当前层若已有同名则冲突（或合法重载，本课默认不允许）。遇使用：查找，失败则未声明。记录指针写回 AST 节点，后续不再比字符串。</p>',11)),(e(),n(p,null,{default:o(()=>[d(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20USE%5B%22%E4%BD%BF%E7%94%A8%20x%22%5D%20--%3E%20LOOK%5B%22%E4%BB%8E%E5%86%85%E5%B1%82%E5%90%91%E5%A4%96%E6%9F%A5%22%5D%0A%20%20LOOK%20--%3E%20BIND%5B%22%E7%BB%91%E5%AE%9A%E5%88%B0%E5%A3%B0%E6%98%8E%22%5D%0A%20%20LOOK%20--%3E%20ERR%5B%22%E6%9C%AA%E5%A3%B0%E6%98%8E%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>模块导入、命名空间是多层中的横向边，本课点名：仍是查找路径，不是新的图算法。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>编译期符号表不必留到运行时；调试信息可以。运行时栈帧布局在 ABI 课按记录的偏移填。<a href="/cs/riscv-int-isa">RISC-V 寄存器</a>还没选，偏移可以先按抽象槽。同名函数重载要带类型键，留给类型课。</p><p>宏与卫生宏会打乱「源里看见的名字」，本课不处理。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不检查类型、不做隐式转换、不解析方法分派（虚表是后话）。不处理链接期的全局符号解析——那是<a href="/cs/link-reloc">链接</a>的另一张表。后课默认：AST 上的名字已绑到声明。类型是否合法是下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>词法作用域 = 嵌套层叠；内层遮蔽外层。</li><li>符号表实现查找；绑定写回 AST。</li><li>未声明与重复声明在本课报告。</li><li>出处：Aho et al., 龙书第 2、6 章。</li></ul>',8))])}const B=s(h,[["render",_]]);export{b as __pageData,B as default};
